def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        if i == n:
            # End of line
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    i += 1
                    if i < n and line[i] == '"':
                        # Doubled quote
                        field.append('"')
                        i += 1
                    else:
                        # End of quoted field
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None

            # Check what follows the closing quote
            if i < n and line[i] != ',':
                # Closing quote must be followed by comma or end of line
                return None

            fields.append(''.join(field))

            if i < n:
                # Skip the comma
                i += 1
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field must not contain quotes
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))

            if i < n:
                # Skip the comma
                i += 1

    return fields

